import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO
def task_func(url, table_id):
    response = requests.get(url)
    try:
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(str(e)) from e
    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)
    if table is None:
        raise ValueError("Table with the specified ID not found.")
    rows = table.find_all('tr')
    if not rows:
        return pd.DataFrame()
    data = []
    for row in rows:
        cells = row.find_all(['th', 'td'])
        if not cells:
            continue
        data.append([cell.get_text(strip=True) for cell in cells])
    if not data:
        return pd.DataFrame()
    header = None
    if table.find('th') is not None:
        header = data[0]
        data_rows = data[1:]
    else:
        data_rows = data
    df = pd.DataFrame(data_rows, columns=header if header is not None else None)
    return df

