from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    is_url = webpage_url.startswith("http://") or webpage_url.startswith("https://")
    if is_url:
        try:
            response = requests.get(webpage_url)
            response.raise_for_status()
            content = response.text
        except requests.RequestException as e:
            raise requests.RequestException(f"Error fetching URL: {e}")
    else:
        path = webpage_url
        if webpage_url.startswith("file://"):
            path = webpage_url[7:]
        with open(path, "r", encoding="utf-8") as f:
            content = f.read()
    root = html.fromstring(content)
    table_elements = root.xpath("//table")
    if not table_elements:
        return 0
    table = table_elements[0]
    rows = table.xpath(".//tr")
    data_rows = []
    headers = []
    header_cells = rows[0].xpath(".//th")
    if header_cells:
        headers = [cell.text_content().strip() for cell in header_cells]
        data_start_index = 1
    else:
        data_start_index = 0
    for row in rows[data_start_index:]:
        cells = row.xpath(".//td")
        if not cells:
            continue
        data_rows.append([cell.text_content().strip() for cell in cells])
    if not data_rows:
        return 0
    if not headers:
        max_len = max(len(r) for r in data_rows)
        headers = [f"col_{i}" for i in range(max_len)]
        normalized_rows = []
        for r in data_rows:
            if len(r) < max_len:
                r = r + [None] * (max_len - len(r))
            normalized_rows.append(r)
        data_rows = normalized_rows
    df = pd.DataFrame(data_rows, columns=headers)
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return len(df)

