import logging
def task_func(repo_url: str) -> dict:
    if not isinstance(repo_url, str) or not repo_url.strip():
        raise requests.exceptions.RequestException("Repository URL must be a non-empty string.")
    try:
        response = requests.get(repo_url, timeout=10)
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Error during request to GitHub API: {e}")
    try:
        if not response.ok:
            if response.status_code == 403:
                limit = response.headers.get("X-RateLimit-Limit")
                remaining = response.headers.get("X-RateLimit-Remaining")
                reset = response.headers.get("X-RateLimit-Reset")
                msg = "GitHub API rate limit may have been exceeded."
                if limit is not None or remaining is not None or reset is not None:
                    msg += f" Limit: {limit}, Remaining: {remaining}, Reset: {reset}"
                raise requests.exceptions.HTTPError(msg, response=response)
            response.raise_for_status()
        data = response.json()
    except requests.exceptions.HTTPError as e:
        raise
    except ValueError as e:
        raise requests.exceptions.RequestException(f"Invalid JSON response from GitHub API: {e}")
    open_issues = data.get("open_issues_count")
    threshold = 1000
    if isinstance(open_issues, int) and open_issues > threshold:
        logging.warning(f"Repository has a high number of open issues: {open_issues}")
    return data

