import re
import json
import requests
def task_func(data_url: str) -> list:
    if not isinstance(data_url, str) or not data_url:
        return "Invalid url input"
    try:
        response = requests.get(data_url, timeout=10)
        text = response.text
    except Exception:
        return "Invalid url input"
    pattern = r'"name"\s*:\s*"([^"]+)"'
    names = []
    for match in re.finditer(pattern, text):
        name = match.group(1)
        start = match.start()
        end = match.end()
        before = text[:start]
        after = text[end:]
        inside_brackets = False
        idx_open = before.rfind('[')
        idx_close = before.rfind(']')
        if idx_open != -1 and (idx_close == -1 or idx_open > idx_close):
            idx_close_after = after.find(']')
            if idx_close_after != -1:
                inside_brackets = True
        if not inside_brackets:
            names.append(name)
    return names

