import json
import requests
def task_func(data_url: str) -> list:
    if not isinstance(data_url, str) or not data_url.strip():
        return ["Invalid url input"]
    try:
        response = requests.get(data_url)
        text = response.text
    except Exception:
        return ["Invalid url input"]
    pattern = r'"name"\s*:\s*"(.*?)"|\'name\'\s*:\s*\'(.*?)\''
    all_matches = re.findall(pattern, text)
    all_names = []
    for m in all_matches:
        name = m[0] if m[0] else m[1]
        if name:
            all_names.append(name)
    bracket_pattern = r'\[(?:[^\[\]]*?\{[^{}]*?"name"\s*:\s*"(.*?)"[^{}]*?\}[^\[\]]*?|\s*)*?\]'
    bracket_pattern_alt = r'\[(?:[^\[\]]*?\{[^{}]*?\'name\'\s*:\s*\'(.*?)\'[^{}]*?\}[^\[\]]*?|\s*)*?\]'
    bracketed_names = set()
    for segment in re.findall(bracket_pattern, text, flags=re.DOTALL):
        if segment:
            bracketed_names.add(segment)
    for segment in re.findall(bracket_pattern_alt, text, flags=re.DOTALL):
        if segment:
            bracketed_names.add(segment)
    result = [n for n in all_names if n not in bracketed_names]
    return result

