import re
import requests
import json
import csv
import os
API_URL = 'https://api.example.com/data'
def task_func(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ValueError("Pattern must be a non-empty string.")
    regex = re.compile(pattern)
    response = requests.get(API_URL)
    response.raise_for_status()
    try:
        payload = response.json()
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON response: {e}")
    if "data" not in payload:
        data_items = []
    else:
        data_items = payload["data"]
    if isinstance(data_items, str):
        data_items = [data_items]
    elif not isinstance(data_items, (list, tuple)):
        data_items = [str(data_items)]
    matches = []
    for item in data_items:
        text = str(item)
        found = regex.findall(text)
        if isinstance(found, list):
            for m in found:
                if isinstance(m, tuple):
                    matches.extend([x for x in m if x])
                else:
                    matches.append(m)
    csv_filename = "matched_data.csv"
    abs_path = os.path.abspath(csv_filename)
    with open(csv_filename, "w", newline="") as f:
        writer = csv.writer(f)
        for m in matches:
            writer.writerow([m])
    return abs_path

